  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly attributes a positive outcome, achievement, or benefit to their own actions, efforts, or advocacy, thereby seeking recognition or taking personal responsibility for the result.",
    "clarification": "Credit-claiming is identified when a senator uses language such as 'I secured,' 'I helped,' 'I authored,' 'I fought for,' or similar phrasing to directly link themselves to a successful outcome, funding allocation, legislative achievement, or other positive development. The focus is on the senator's explicit assertion of their role in bringing about the result.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states, 'I authored legislation, which was signed into law, that created the National Center designation,' directly linking his actions to the achievement of the designation for Bismarck State College."
      },
